def transform(grid):
    h, w = len(grid), len(grid[0])
    sep = next((r for r in range(h) if all(v == grid[r][0] for v in grid[r])), None)
    if sep is None:
        return [[1]]
    bg = next(v for v in grid[0] if v != grid[0][0])
    hr = [r for r in range(h) if all(v == bg for v in grid[r])]
    vc = [c for c in range(w) if all(grid[r][c] == bg for r in range(h))]
    rb = [-1] + hr + [h]
    cb = [-1] + vc + [w]
    rh = rb[1] - rb[0] - 1
    cw = cb[1] - cb[0] - 1
    out = [[5] * cw for _ in range(rh)]
    for i in range(rh):
        for j in range(cw):
            n = 0
            for a in range(len(rb)-1):
                for b in range(len(cb)-1):
                    r0, r1 = rb[a]+1, rb[a+1]
                    c0, c1 = cb[b]+1, cb[b+1]
                    if r0+i < r1 and c0+j < c1 and grid[r0+i][c0+j] not in (bg, 5):
                        n += 1
            if n % 2 == 0:
                out[i][j] = 1
    return out
